[
  // ==================== BASICS (25) ====================
  ["PostgreSQL", "What is PostgreSQL and what are its main features?", "postgresql-overview", "Define PostgreSQL and list key features.", "PostgreSQL is a powerful, open-source object-relational database management system (ORDBMS) known for its reliability, feature robustness, and performance. Key features: ACID compliance, MVCC (Multi-Version Concurrency Control), advanced indexing (B-tree, GIN, GiST, BRIN), full-text search, JSON/JSONB support, user-defined data types, extensions (PostGIS, pgcrypto), and support for procedural languages (PL/pgSQL, PL/Python, PL/Perl)."],
  ["PostgreSQL", "What is the difference between PostgreSQL and MySQL?", "postgresql-vs-mysql", "Compare the two databases.", "PostgreSQL is an object-relational database with advanced features like custom types, inheritance, and complex queries. It is fully ACID compliant and supports advanced concurrency control (MVCC). MySQL is a relational database known for speed and simplicity, often used for web applications. PostgreSQL excels in complex analytics, data integrity, and extensibility; MySQL is preferred for simpler OLTP workloads."],
  ["PostgreSQL", "What is the difference between a database and a schema in PostgreSQL?", "database-vs-schema", "Explain the hierarchy.", "A database is a top-level container that holds multiple schemas. A schema is a logical namespace within a database that contains database objects (tables, views, functions, etc.). Schemas help organize objects and manage permissions. A single database can have many schemas."],
  ["PostgreSQL", "What is a tablespace in PostgreSQL?", "tablespace-definition", "Define the storage location.", "A tablespace is a directory on the filesystem where PostgreSQL stores data files. It allows administrators to control the physical storage location of databases and tables. This is useful for performance optimization (SSD vs HDD) or space management."],
  ["PostgreSQL", "What is MVCC and how does it work in PostgreSQL?", "mvcc-definition", "Explain Multi-Version Concurrency Control.", "MVCC is a concurrency control mechanism where each transaction sees a snapshot of the database at a specific point in time. Instead of locking rows for reads, PostgreSQL creates a new version of a row on updates. The old version is kept until no transaction needs it. This allows high concurrency without read/write contention."],
  ["PostgreSQL", "Explain the `VACUUM` command and why it is important.", "vacuum-definition", "Define VACUUM and its purpose.", "VACUUM reclaims storage occupied by dead rows (caused by updates/deletes). It also updates statistics for the query planner. Without VACUUM, tables can bloat, leading to performance degradation. `VACUUM FULL` (or `CLUSTER`) reclaims space but locks the table; regular `VACUUM` is non-blocking."],
  ["PostgreSQL", "What is `ANALYZE` and when should you run it?", "analyze-definition", "Explain the command.", "`ANALYZE` collects statistics about the contents of tables. The query planner uses these statistics to choose efficient execution plans. It is automatically run by autovacuum, but you can manually run it after significant data changes to improve query performance."],
  ["PostgreSQL", "What is the role of `autovacuum`?", "autovacuum-definition", "Explain the background process.", "`autovacuum` is a background process that automatically runs VACUUM and ANALYZE based on configurable thresholds (dead row count). It prevents table bloat and ensures up-to-date statistics. It is enabled by default and should be tuned for large workloads."],
  ["PostgreSQL", "What are the default ports for PostgreSQL?", "postgresql-port", "Specify the default port.", "The default port for PostgreSQL is 5432."],
  ["PostgreSQL", "How do you connect to a PostgreSQL database?", "connect-postgresql", "Explain the connection methods.", "You can connect using: 1) `psql` command-line tool: `psql -h host -p port -U username -d database`. 2) Connection strings: `postgresql://user:password@host:port/db`. 3) GUI tools like pgAdmin. 4) Application libraries (psycopg2 for Python, JDBC for Java)."],
  ["PostgreSQL", "What is the difference between `SELECT *` and `SELECT col1, col2` performance-wise?", "select-star-vs-columns", "Explain the impact.", "`SELECT *` fetches all columns, which can lead to unnecessary data transfer and slower performance, especially for wide tables. `SELECT col1, col2` only retrieves needed columns, reducing I/O and memory usage. Always specify columns for production queries."],
  ["PostgreSQL", "Explain the `DISTINCT` clause.", "distinct-clause", "Define the clause.", "`DISTINCT` removes duplicate rows from the result set. It can be applied to a single column or a combination of columns. It often requires sorting, which can be expensive on large tables."],
  ["PostgreSQL", "What is the difference between `WHERE` and `HAVING`?", "where-vs-having", "Compare the two.", "`WHERE` filters rows before grouping (applies to individual rows). `HAVING` filters groups after grouping (applies to aggregate functions). `HAVING` is used with `GROUP BY`."],
  ["PostgreSQL", "Explain the `GROUP BY` clause.", "group-by-clause", "Define the clause.", "`GROUP BY` groups rows that have the same values in specified columns into summary rows. It is often used with aggregate functions like `COUNT`, `SUM`, `AVG`, `MAX`, `MIN`."],
  ["PostgreSQL", "What is the difference between `INNER JOIN` and `LEFT JOIN`?", "inner-vs-left-join", "Compare the two joins.", "`INNER JOIN` returns only rows where there is a match in both tables. `LEFT JOIN` (or `LEFT OUTER JOIN`) returns all rows from the left table, and matching rows from the right table; if no match, columns from the right table are NULL."],
  ["PostgreSQL", "What is a CTE (Common Table Expression)?", "cte-definition", "Define the WITH clause.", "A CTE is a temporary result set defined using the `WITH` clause. It simplifies complex queries by breaking them into readable parts. CTEs can be recursive, enabling hierarchical queries (e.g., tree traversal)."],
  ["PostgreSQL", "What is the difference between a view and a materialized view?", "view-vs-materialized-view", "Compare the two.", "A view is a virtual table defined by a query; it does not store data. A materialized view stores the query result physically and can be refreshed (like a cache). Materialized views improve read performance but require periodic refresh."],
  ["PostgreSQL", "What is an index in PostgreSQL?", "index-definition", "Define the database object.", "An index is a data structure that improves the speed of data retrieval operations (SELECT). It is like a book index. PostgreSQL supports several index types: B-tree (default), Hash, GiST, GIN, BRIN, and SP-GiST. Indexes add overhead on INSERT/UPDATE/DELETE."],
  ["PostgreSQL", "What is the default index type in PostgreSQL?", "default-index-type", "Specify the default.", "The default index type is B-tree."],
  ["PostgreSQL", "Explain the `EXPLAIN` command.", "explain-definition", "Define the query analysis tool.", "`EXPLAIN` shows the execution plan of a query. It helps identify bottlenecks (e.g., sequential scans, sorts). `EXPLAIN ANALYZE` runs the query and provides actual runtime statistics. Use it to optimize slow queries."],
  ["PostgreSQL", "What is the difference between `UNION` and `UNION ALL`?", "union-vs-union-all", "Compare the two.", "`UNION` combines results from two queries and removes duplicate rows. `UNION ALL` combines results without removing duplicates. `UNION` is slower because it requires sorting to eliminate duplicates; use `UNION ALL` when duplicates are acceptable."],
  ["PostgreSQL", "What is a sequence in PostgreSQL?", "sequence-definition", "Explain the auto-increment generator.", "A sequence is a database object that generates a series of unique numbers. It is commonly used for auto-incrementing primary keys with the `SERIAL` or `BIGSERIAL` data type. You can also create custom sequences using `CREATE SEQUENCE`."],
  ["PostgreSQL", "What is `TRUNCATE` and how does it differ from `DELETE`?", "truncate-vs-delete", "Compare the two.", "`TRUNCATE` removes all rows from a table quickly by deallocating data pages; it is DDL and cannot be rolled back (in most cases unless in a transaction). `DELETE` removes rows one by one (DML) and is slower; it can be rolled back. `TRUNCATE` resets auto-increment counters; `DELETE` does not unless specified."],
  ["PostgreSQL", "Explain the concept of a transaction in PostgreSQL.", "transaction-definition", "Define ACID and transaction.", "A transaction is a sequence of database operations treated as a single unit of work. It follows ACID properties: Atomicity (all or nothing), Consistency (valid state), Isolation (concurrent transactions are isolated), Durability (committed changes persist). In PostgreSQL, transactions are started with `BEGIN` and ended with `COMMIT` or `ROLLBACK`."],
  ["PostgreSQL", "What are the isolation levels in PostgreSQL?", "isolation-levels-postgres", "List and explain.", "PostgreSQL supports four isolation levels: READ UNCOMMITTED (actually READ COMMITTED in behavior), READ COMMITTED (default), REPEATABLE READ, and SERIALIZABLE. They control the visibility of changes made by concurrent transactions. The default is READ COMMITTED."],

  // ==================== DATA TYPES (15) ====================
  ["PostgreSQL", "What are the common numeric data types in PostgreSQL?", "numeric-types", "List and describe.", "Common numeric types: `INTEGER` (4 bytes), `BIGINT` (8 bytes), `SMALLINT` (2 bytes), `DECIMAL`/`NUMERIC` (exact arithmetic), `REAL` (4 bytes floating), `DOUBLE PRECISION` (8 bytes floating), and `SERIAL` (auto-incrementing integer)."],
  ["PostgreSQL", "What is the difference between `CHAR`, `VARCHAR`, and `TEXT`?", "char-varchar-text", "Compare the string types.", "`CHAR(n)` is fixed-length with blank padding. `VARCHAR(n)` is variable-length with a limit. `TEXT` is variable-length without a limit. In PostgreSQL, performance is similar for all; use `TEXT` for flexibility unless you need length constraints."],
  ["PostgreSQL", "What is the `JSONB` data type and how does it differ from `JSON`?", "json-vs-jsonb", "Compare JSON storage.", "`JSON` stores JSON data as plain text, preserving whitespace and order. `JSONB` stores JSON in a decomposed binary format, which is faster for querying and indexing because it does not need to be reparsed. `JSONB` also supports indexing (GIN) and more operators. `JSONB` is recommended for most use cases."],
  ["PostgreSQL", "What is the `ARRAY` data type and how do you use it?", "array-data-type", "Explain and give examples.", "PostgreSQL supports arrays of any data type. You can define a column as `INTEGER[]`, `TEXT[]`, etc. Use `array_agg` to aggregate into arrays, and operators like `@>` (contains) for queries. Example: `SELECT * FROM table WHERE 'apple' = ANY(fruits)`."],
  ["PostgreSQL", "What is the `UUID` data type?", "uuid-type", "Define and explain usage.", "`UUID` stores Universally Unique Identifiers as per RFC 4122. It is a 128-bit value. Use the `gen_random_uuid()` function to generate random UUIDs. It is suitable for primary keys in distributed systems."],
  ["PostgreSQL", "What is the difference between `TIMESTAMP` and `TIMESTAMPTZ`?", "timestamp-vs-timestamptz", "Compare the timestamp types.", "`TIMESTAMP` (without time zone) stores a date and time without time zone information. `TIMESTAMPTZ` (with time zone) stores a timestamp and converts it to UTC internally; it handles time zone conversion on retrieval. Always use `TIMESTAMPTZ` for global applications."],
  ["PostgreSQL", "What is the `BYTEA` data type?", "bytea-type", "Define and explain usage.", "`BYTEA` stores binary data (e.g., images, files) as a byte array. It is similar to BLOB in other databases. Use it for small to medium binary objects; for large files, consider using external storage."],
  ["PostgreSQL", "What are range types and how are they used?", "range-types", "Define and give examples.", "Range types represent a range of values (e.g., date ranges, number ranges). Examples: `INT4RANGE`, `DATERANGE`, `TSRANGE`. Operators like `&&` (overlap), `@>` (contains) are used. Useful for scheduling, inventory management, and gap detection."],
  ["PostgreSQL", "What is the `ENUM` data type?", "enum-type", "Define and explain usage.", "`ENUM` defines a static set of values (e.g., 'pending', 'approved', 'rejected'). It ensures data integrity by restricting values to the predefined set. It is stored efficiently and can be ordered by definition order."],
  ["PostgreSQL", "What is the difference between `BOOLEAN` and `BOOL`?", "boolean-vs-bool", "Clarify the types.", "They are the same; `BOOL` is just a synonym for `BOOLEAN`. It stores true/false values."],
  ["PostgreSQL", "What is the `INET` data type?", "inet-type", "Define and explain usage.", "`INET` stores IPv4 or IPv6 addresses. It supports network-related operators (e.g., contains, subnet). Useful for storing client IPs and network configurations."],
  ["PostgreSQL", "What is the `HSTORE` data type?", "hstore-type", "Define and explain usage.", "`HSTORE` is a key-value store within PostgreSQL. It stores sets of key-value pairs as a single value. It is lightweight and supports operations like `->` to get a value. Useful for semi-structured data."],
  ["PostgreSQL", "What is the `JSONPATH` data type?", "jsonpath-definition", "Explain the query language for JSON.", "`JSONPATH` is a query language for JSON data in PostgreSQL. It allows extracting and filtering JSON data using expressions like `$.store.book[*].price`. It is used with the `@>` and `?` operators for efficient JSON querying."],
  ["PostgreSQL", "What is the `CIDR` data type?", "cidr-type", "Define and explain usage.", "`CIDR` stores an IP address with a network mask (e.g., '192.168.0.0/24'). It is used for subnet management and network address calculations. It supports containment operators (`>>` and `<<`)."],
  ["PostgreSQL", "What is the `MONEY` data type?", "money-type", "Define and explain usage.", "`MONEY` stores currency amounts with a fixed fractional precision (usually 2 decimal places). It is locale-aware and handles formatting. However, for precise calculations, use `NUMERIC`."],

  // ==================== INDEXING & PERFORMANCE (20) ====================
  ["PostgreSQL", "Explain the different index types in PostgreSQL.", "index-types", "List and describe.", "B-tree: default, balanced tree for equality and range queries. GiST: generalized search tree for complex data (geometry, full-text). GIN: inverted index for array, JSONB, and full-text search. BRIN: block range index for large tables with natural ordering. SP-GiST: space-partitioned GiST for specialized data. Hash: equality only."],
  ["PostgreSQL", "What is a partial index and when would you use it?", "partial-index", "Define and give use cases.", "A partial index is an index on a subset of rows, defined by a `WHERE` clause. It saves space and improves performance by indexing only frequently queried rows (e.g., only active orders). Example: `CREATE INDEX idx_active_orders ON orders (order_date) WHERE status = 'active'`."],
  ["PostgreSQL", "What is the difference between a B-tree and a GIN index?", "btree-vs-gin", "Compare the two.", "B-tree supports equality and range queries (`=`, `<`, `>`, `BETWEEN`) on scalar data. GIN is designed for composite data types (arrays, JSONB, full-text) and supports containment (`@>`) and overlap (`&&`) queries. GIN is slower to update but faster for complex searches."],
  ["PostgreSQL", "What is a BRIN index and when is it useful?", "brin-index", "Define and explain use cases.", "BRIN (Block Range Index) stores summary information about ranges of blocks. It is very small and efficient for very large tables where data is naturally ordered (e.g., timestamp columns). It is ideal for scanning a subset of rows in a large table (e.g., date range queries on a log table)."],
  ["PostgreSQL", "How do you analyze query performance in PostgreSQL?", "query-performance-analysis", "Explain the steps.", "1. Use `EXPLAIN ANALYZE` to view the execution plan and actual timings. 2. Look for sequential scans on large tables. 3. Check for sorts, hash joins, or nested loops that might be slow. 4. Verify that indexes are being used. 5. Ensure statistics are up-to-date (`ANALYZE`). 6. Consider query rewriting or index tuning."],
  ["PostgreSQL", "What is a sequential scan and why is it generally slower?", "sequential-scan", "Define and explain.", "A sequential scan reads every block of a table sequentially to find matching rows. It is slow for large tables because it does full table I/O. It is used when no suitable index exists or when the table is small or when a large fraction of the table is expected to be returned."],
  ["PostgreSQL", "How do you force an index scan?", "force-index-scan", "Explain techniques.", "You can use `SET enable_seqscan = off` temporarily (not recommended in production) to discourage sequential scans. Better to analyze why the planner is not using an index: check statistics, ensure the query is selective, and consider partial indexes or covering indexes."],
  ["PostgreSQL", "What is a covering index?", "covering-index", "Define the concept.", "A covering index is an index that includes all columns needed for a query, so the query can be satisfied entirely from the index without accessing the table (i.e., index-only scan). In PostgreSQL, you can use `CREATE INDEX ... INCLUDE (col)` to include non-key columns."],
  ["PostgreSQL", "What is the `pg_stat_statements` extension and how is it used?", "pg-stat-statements", "Explain the extension.", "`pg_stat_statements` tracks execution statistics for all SQL statements, including planning time, execution time, and rows returned. It helps identify the most time-consuming queries and optimize them. It is enabled by creating the extension."],
  ["PostgreSQL", "How do you monitor PostgreSQL performance?", "monitor-postgresql", "List tools and metrics.", "Tools: `pg_stat_activity` for current queries, `pg_stat_statements` for statement stats, `pg_stat_replication` for replication status, `pg_stat_database` for database-level stats. Metrics: CPU, memory, disk I/O, and connection count. Use external monitoring like Prometheus with postgres_exporter or pgAdmin."],
  ["PostgreSQL", "What is the purpose of the `explain` buffer and timing options?", "explain-buffers", "Explain the options.", "`EXPLAIN (BUFFERS)` shows buffer usage (shared, local, temp) for the query. `EXPLAIN (TIMING)` includes time spent on each plan node. These options help diagnose I/O bottlenecks and identify expensive steps."],
  ["PostgreSQL", "What is table partitioning and how does it improve performance?", "table-partitioning", "Explain the concept.", "Table partitioning splits a large table into smaller, more manageable pieces (partitions) based on a key (e.g., date). It improves query performance by allowing partition pruning (scanning only relevant partitions), reduces index size, and simplifies data archival."],
  ["PostgreSQL", "What are the partitioning methods in PostgreSQL?", "partitioning-methods", "List and describe.", "RANGE partitioning (by date range), LIST partitioning (by discrete values), and HASH partitioning (for distributing data evenly). Available in PostgreSQL 10+. Also, declarative partitioning is preferred over inheritance-based."],
  ["PostgreSQL", "What is the difference between partitioning and sharding?", "partitioning-vs-sharding", "Compare the two.", "Partitioning is a database-level technique to split a table within a single database instance. Sharding is a horizontal scaling technique where data is distributed across multiple independent database instances (often on different servers). Sharding is for scalability across nodes; partitioning is for manageability and performance within a node."],
  ["PostgreSQL", "How do you create a multi-column index?", "multi-column-index", "Provide syntax.", "`CREATE INDEX idx_name ON table (col1, col2);`. Multi-column indexes are useful when queries filter on both columns. The order of columns matters: the leftmost prefix is most important."],
  ["PostgreSQL", "What is a functional index?", "functional-index", "Define and give examples.", "A functional index uses an expression or function (e.g., `LOWER(col)`). It is useful for case-insensitive searches or querying on derived values. Example: `CREATE INDEX idx_lower_name ON users (LOWER(name));`."],
  ["PostgreSQL", "How do you check if an index is being used?", "check-index-usage", "Explain methods.", "Use `EXPLAIN` to see if the index is used in the plan. Check `pg_stat_user_indexes` for index usage counts (`idx_scan`). If an index is never scanned, consider dropping it."],
  ["PostgreSQL", "What is the `pg_stat_activity` view useful for?", "pg-stat-activity", "Explain its content.", "`pg_stat_activity` shows current connections, active queries, their states, and wait events. It is useful for identifying long-running queries, blocking processes, and idle connections. Use it for troubleshooting performance issues."],
  ["PostgreSQL", "How do you use `pgbench`?", "pgbench-definition", "Explain the benchmarking tool.", "`pgbench` is a benchmarking tool for PostgreSQL. It runs a series of SQL transactions and measures performance (TPS). It helps test hardware and configuration changes. Example: `pgbench -i -s 10 testdb` initializes; `pgbench -c 10 -j 2 -t 1000 testdb` runs the test."],
  ["PostgreSQL", "What is the purpose of the `auto_explain` module?", "auto-explain", "Explain the extension.", "`auto_explain` logs the execution plans of slow queries automatically. It is enabled by loading the module and setting parameters like `auto_explain.log_min_duration`. It helps capture slow queries without manual EXPLAIN."],

  // ==================== PL/pgSQL & FUNCTIONS (15) ====================
  ["PostgreSQL", "What is PL/pgSQL?", "plpgsql-definition", "Define the procedural language.", "PL/pgSQL is PostgreSQL's procedural language, similar to PL/SQL in Oracle. It allows writing functions, triggers, and stored procedures with control structures (loops, conditionals). It improves performance by reducing client-server round trips and provides tighter integration with SQL."],
  ["PostgreSQL", "How do you create a function in PostgreSQL?", "create-function", "Provide syntax and example.", "`CREATE FUNCTION function_name (param1 type, ...) RETURNS type AS $$ BEGIN ... END; $$ LANGUAGE plpgsql;`. Example: `CREATE FUNCTION add(a INTEGER, b INTEGER) RETURNS INTEGER AS $$ BEGIN RETURN a + b; END; $$ LANGUAGE plpgsql;`"],
  ["PostgreSQL", "What is the difference between a function and a procedure?", "function-vs-procedure", "Explain the distinction.", "A function returns a value and can be used in SQL expressions. A procedure (introduced in PostgreSQL 11) does not return a value and is called with `CALL`. Procedures are used for transactions and server-side operations."],
  ["PostgreSQL", "What is a trigger and how is it used in PostgreSQL?", "trigger-definition", "Define and explain usage.", "A trigger is a function that automatically executes before or after a DML operation (INSERT, UPDATE, DELETE) on a table. It is used for auditing, validation, and maintaining derived data. Triggers are defined using `CREATE TRIGGER`."],
  ["PostgreSQL", "What is the difference between `BEFORE` and `AFTER` triggers?", "before-vs-after-trigger", "Compare the two.", "`BEFORE` trigger fires before the operation, allowing modification of the row (e.g., for validation). `AFTER` trigger fires after the operation, used for actions like logging or cascading updates."],
  ["PostgreSQL", "What are `RETURNS TABLE` and `RETURNS SETOF`?", "returns-table-vs-setof", "Explain the return types.", "`RETURNS TABLE (col1 type, col2 type)` defines a function that returns a set of rows with specified columns. `RETURNS SETOF` returns a set of rows of a specified table type. Both are used for table-valued functions."],
  ["PostgreSQL", "How do you handle exceptions in PL/pgSQL?", "exception-handling-plpgsql", "Explain the `EXCEPTION` block.", "Use `BEGIN ... EXCEPTION ... END` blocks. Example: `BEGIN ... EXCEPTION WHEN others THEN RAISE NOTICE 'Error: %', SQLERRM; END;`."],
  ["PostgreSQL", "What is a custom data type in PostgreSQL?", "custom-data-type", "Explain using `CREATE TYPE`.", "You can create custom data types using `CREATE TYPE` (for composite types) or `CREATE DOMAIN` (to create a type with constraints). Custom types improve data integrity and expressiveness. Example: `CREATE TYPE address AS (street TEXT, city TEXT, zip TEXT)`."],
  ["PostgreSQL", "How do you write a recursive CTE?", "recursive-cte", "Provide an example.", "Use `WITH RECURSIVE` to define a recursive query. Example for a tree: `WITH RECURSIVE tree AS (SELECT id, parent_id, name FROM nodes WHERE parent_id IS NULL UNION ALL SELECT n.id, n.parent_id, n.name FROM nodes n JOIN tree t ON n.parent_id = t.id) SELECT * FROM tree;`."],
  ["PostgreSQL", "What is the `RAISE` command used for?", "raise-command", "Explain debugging and error signaling.", "`RAISE` is used in PL/pgSQL to raise errors or messages. It can output notices, warnings, or fatal errors. Useful for debugging and logging. Example: `RAISE NOTICE 'Value: %', my_var;`."],
  ["PostgreSQL", "What is the `RETURNING` clause?", "returning-clause", "Explain its use.", "`RETURNING` returns values from the affected rows in INSERT, UPDATE, or DELETE. Example: `UPDATE users SET status = 'active' WHERE id = 1 RETURNING id, updated_at;`. It avoids a separate SELECT."],
  ["PostgreSQL", "What is a window function? Give an example.", "window-function", "Define and provide an example.", "Window functions perform calculations across a set of rows related to the current row, without grouping them. Examples: `ROW_NUMBER()`, `RANK()`, `LAG()`, `LEAD()`. Example: `SELECT id, sales, RANK() OVER (ORDER BY sales DESC) FROM orders;`"],
  ["PostgreSQL", "What is the `COALESCE` function?", "coalesce-function", "Define and give an example.", "`COALESCE` returns the first non-NULL value from a list. Example: `SELECT COALESCE(phone, mobile, 'No contact') FROM users;`. Useful for handling NULLs."],
  ["PostgreSQL", "What is the `NULLIF` function?", "nullif-function", "Define and give an example.", "`NULLIF` returns NULL if the two arguments are equal, otherwise returns the first argument. Example: `SELECT NULLIF(score, 0) FROM tests;`."],
  ["PostgreSQL", "What are `LATERAL` joins?", "lateral-joins", "Explain the concept.", "`LATERAL` allows a subquery to reference columns from preceding tables in the `FROM` clause. It is useful for writing subqueries that depend on previous rows. Example: `SELECT u.name, q.* FROM users u, LATERAL (SELECT * FROM orders WHERE user_id = u.id LIMIT 1) q;`."],

  // ==================== ADMINISTRATION & BACKUP (15) ====================
  ["PostgreSQL", "How do you backup a PostgreSQL database?", "backup-methods", "Explain the methods.", "Two main methods: 1) `pg_dump` for logical backups (SQL or custom format) – `pg_dump -U username -d dbname > backup.sql`. 2) `pg_basebackup` for physical backups (file-level) used for replication. Use `pg_dumpall` for backing up all databases and global objects."],
  ["PostgreSQL", "How do you restore a backup?", "restore-backup", "Explain the restore process.", "For `pg_dump` backups: use `psql -U username -d dbname < backup.sql` or `pg_restore -d dbname backup.dump` for custom format. For physical backups: use `pg_basebackup` or filesystem restore, then apply WAL logs."],
  ["PostgreSQL", "What is WAL (Write-Ahead Logging) and why is it important?", "wal-definition", "Define and explain its purpose.", "WAL is a log that records all changes to the database before they are written to the data files. It ensures durability (crash recovery) and enables replication (streaming replication, point-in-time recovery). WAL files are stored in the `pg_wal` directory."],
  ["PostgreSQL", "How do you perform point-in-time recovery (PITR)?", "pitr-definition", "Explain the process.", "PITR uses continuous archiving of WAL logs. To recover to a specific time: 1) Restore a base backup. 2) Set `recovery_target_time` in `recovery.conf`. 3) Start PostgreSQL; it replays WAL logs to reach the target time."],
  ["PostgreSQL", "What is streaming replication?", "streaming-replication", "Define and explain.", "Streaming replication is a method of replicating data from a primary server to one or more standby servers in real-time. It uses WAL streaming. Standby servers can be in recovery mode (read-only) and can take over as primary in case of failure."],
  ["PostgreSQL", "What is the difference between synchronous and asynchronous replication?", "sync-vs-async-replication", "Compare the two.", "Synchronous replication: the primary waits for at least one standby to confirm that the WAL has been received and flushed, ensuring no data loss, but increases transaction latency. Asynchronous replication: the primary does not wait; faster but risk of data loss if the primary crashes."],
  ["PostgreSQL", "How do you promote a standby to primary?", "promote-standby", "Explain the steps.", "On the standby server, run `pg_ctl promote` or create a trigger file (if configured). This switches the standby to primary mode (read-write). Then reconfigure the old primary (if recovering) or other standbys to replicate from the new primary."],
  ["PostgreSQL", "What is the `pg_hba.conf` file used for?", "pg_hba-conf", "Explain client authentication.", "`pg_hba.conf` (Host-Based Authentication) controls which clients can connect to the PostgreSQL server and how they authenticate (e.g., trust, md5, scram-sha-256, cert, peer). It is read at server startup and on reload."],
  ["PostgreSQL", "What is the difference between `trust` and `md5` authentication?", "trust-vs-md5", "Compare the authentication methods.", "`trust` allows any connection without password, used only for local connections in secure environments. `md5` requires a password (hashed with MD5). `scram-sha-256` is stronger than `md5`."],
  ["PostgreSQL", "How do you change a user's password in PostgreSQL?", "change-password", "Provide the command.", "`ALTER USER username WITH PASSWORD 'new_password';`; or using `\\password username` in psql."],
  ["PostgreSQL", "What are roles in PostgreSQL?", "roles-definition", "Explain the concept.", "Roles are PostgreSQL's concept for users and groups. Roles can be `LOGIN` (users) or not. Roles can inherit privileges from other roles, enabling group management. Use `CREATE ROLE` and `GRANT`."],
  ["PostgreSQL", "How do you grant permissions in PostgreSQL?", "grant-permissions", "Provide examples.", "`GRANT SELECT ON table TO user;` for read access. `GRANT INSERT, UPDATE ON table TO group;` for multiple privileges. `GRANT ALL ON DATABASE db TO user;` for database-level permissions. Use `WITH GRANT OPTION` to allow delegation."],
  ["PostgreSQL", "What is the `pg_ctl` utility used for?", "pg-ctl-definition", "Explain the control tool.", "`pg_ctl` is a command-line tool for controlling the PostgreSQL server: start, stop, restart, reload, promote, and status. Example: `pg_ctl -D /var/lib/pgsql/data start`."],
  ["PostgreSQL", "How do you reload the PostgreSQL configuration without restarting?", "reload-config", "Explain the command.", "Use `pg_ctl reload` or `SELECT pg_reload_conf();` in SQL. This reloads configuration files (`postgresql.conf`, `pg_hba.conf`) without restarting the server."],
  ["PostgreSQL", "What are the main configuration parameters in `postgresql.conf`?", "postgresql-conf", "List important parameters.", "Important parameters: `shared_buffers` (memory for caching), `work_mem` (sort/hash memory), `effective_cache_size` (estimate of OS cache), `max_connections` (connection limit), `wal_level` (for replication), `checkpoint_completion_target` (performance), `logging_collector` (logging), and `listen_addresses` (network interface)."],

  // ==================== ADVANCED FEATURES (15) ====================
  ["PostgreSQL", "What is a foreign data wrapper (FDW)?", "fdw-definition", "Explain the feature.", "A foreign data wrapper allows PostgreSQL to access data stored in external systems (other databases, flat files, web APIs) as if it were local tables. It implements the SQL/MED standard. Examples: `postgres_fdw` for remote PostgreSQL, `file_fdw` for CSV files."],
  ["PostgreSQL", "How do you use `postgres_fdw` to connect to a remote database?", "postgres-fdw", "Provide steps.", "1. Install extension: `CREATE EXTENSION postgres_fdw;`. 2. Create a server: `CREATE SERVER remote_server FOREIGN DATA WRAPPER postgres_fdw OPTIONS (host 'host', dbname 'db');`. 3. Create user mapping: `CREATE USER MAPPING FOR local_user SERVER remote_server OPTIONS (user 'remote_user', password 'pwd');`. 4. Create foreign table: `CREATE FOREIGN TABLE remote_table (id INT) SERVER remote_server OPTIONS (schema_name 'schema', table_name 'table');`."],
  ["PostgreSQL", "What is a materialized view and how does it differ from a view?", "materialized-view-definition", "Compare and contrast.", "A materialized view is a database object that stores the result of a query physically. It can be refreshed (`REFRESH MATERIALIZED VIEW`). It improves performance for expensive queries but can be stale. A view is virtual and always up-to-date."],
  ["PostgreSQL", "What is the difference between `CASCADE` and `RESTRICT` in `DROP` commands?", "cascade-vs-restrict", "Explain the options.", "`CASCADE` automatically drops objects that depend on the dropped object (e.g., foreign keys). `RESTRICT` prevents dropping if any dependent objects exist (default). Use `CASCADE` carefully."],
  ["PostgreSQL", "What is the `EXECUTE` command in PL/pgSQL for dynamic SQL?", "execute-dynamic-sql", "Explain the command.", "`EXECUTE` is used to run dynamically constructed SQL strings. It can include parameters using `USING`. Example: `EXECUTE 'SELECT * FROM ' || table_name || ' WHERE id = $1' USING id;`. Always use `USING` to prevent SQL injection."],
  ["PostgreSQL", "What is the `ON CONFLICT` clause (UPSERT)?", "on-conflict", "Explain the upsert functionality.", "`INSERT ... ON CONFLICT (column) DO UPDATE SET ...` allows conditional insertion or update (UPSERT). It resolves conflicts on a unique constraint or index. Example: `INSERT INTO users (id, name) VALUES (1, 'John') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name;`."],
  ["PostgreSQL", "What are row-level security (RLS) policies?", "rls-definition", "Explain the feature.", "RLS allows restricting which rows a user can access based on a policy. It is used for fine-grained access control. Enable RLS on a table: `ALTER TABLE table_name ENABLE ROW LEVEL SECURITY;`. Then create policies using `CREATE POLICY`."],
  ["PostgreSQL", "What is a generated column?", "generated-column", "Define and explain.", "A generated column is a column whose value is automatically computed from other columns. It can be stored (persisted) or virtual (computed on read). Example: `CREATE TABLE products (price NUMERIC, tax NUMERIC, total NUMERIC GENERATED ALWAYS AS (price + tax) STORED);`."],
  ["PostgreSQL", "What is logical replication?", "logical-replication", "Explain the feature.", "Logical replication allows replicating data at a logical level (i.e., using change data capture). It is based on the publication/subscription model. Unlike physical replication, it can replicate selective tables and supports version differences. Available in PostgreSQL 10+."],
  ["PostgreSQL", "What is the difference between logical and physical replication?", "logical-vs-physical-replication", "Compare the two.", "Physical replication replicates the entire cluster at a binary level (WAL). Logical replication replicates changes at the table level, allowing selective replication, filtering, and cross-version replication. Physical is lower-level and more robust."],
  ["PostgreSQL", "What is a stored procedure vs a function in PostgreSQL?", "stored-procedure-vs-function", "Clarify the difference.", "Functions return a value and can be used in SQL expressions. Procedures (introduced in PostgreSQL 11) do not return a value; they are called with `CALL` and can manage transactions. Use procedures for administrative tasks."],
  ["PostgreSQL", "What is the `pg_dump` custom format and how is it different from plain SQL?", "pg-dump-custom", "Explain the custom format.", "The custom format (`-Fc`) creates a compressed, non-text file that supports parallel restore and selective restore. It is faster than plain SQL for large databases and can be used with `pg_restore`. Plain SQL (`-Fp`) is human-readable but slower for large restores."],
  ["PostgreSQL", "What is the purpose of the `REINDEX` command?", "reindex-definition", "Explain the command.", "`REINDEX` rebuilds an index, fixing corruption or bloat. It is useful when indexes become inefficient. It can be done online (`CONCURRENTLY`) to avoid locking the table."],
  ["PostgreSQL", "What is the `CLUSTER` command?", "cluster-definition", "Explain the command.", "`CLUSTER` physically reorders a table based on an index. It improves performance for range queries on that index. It is a one-time operation; use `CLUSTER table_name USING index_name;`. It locks the table."],
  ["PostgreSQL", "What is the `pg_repack` extension?", "pg-repack-definition", "Explain the tool.", "`pg_repack` is a tool to reclaim storage and defragment tables without long locks. It is an alternative to `VACUUM FULL` and `CLUSTER`, offering online operation. It is available as an extension."],

  // ==================== FULL-TEXT SEARCH (10) ====================
  ["PostgreSQL", "What is full-text search in PostgreSQL?", "full-text-search-definition", "Define the feature.", "Full-text search is a feature that allows searching for natural language documents using text search operators and functions. It supports stemming, ranking, and language-specific dictionaries. It uses the `tsvector` (searchable document) and `tsquery` (search query) data types."],
  ["PostgreSQL", "What is the difference between `tsvector` and `tsquery`?", "tsvector-vs-tsquery", "Explain the two types.", "`tsvector` is a sorted list of lexemes (normalized words) representing a document. `tsquery` is a representation of a search query, which can use operators like `&` (AND), `|` (OR), `!` (NOT). Use `to_tsvector` and `to_tsquery` functions."],
  ["PostgreSQL", "How do you index for full-text search?", "fts-index", "Explain the GIN index.", "Create a GIN index on the `tsvector` column. Example: `CREATE INDEX idx_fts ON documents USING GIN (to_tsvector('english', content));`. Then query with `@@` operator: `SELECT * FROM documents WHERE to_tsvector('english', content) @@ to_tsquery('english', 'search');`."],
  ["PostgreSQL", "What is a text search dictionary?", "ts-dictionary", "Define and explain.", "A text search dictionary is used to normalize tokens (e.g., stopping words, synonyms, stemming). PostgreSQL provides several built-in dictionaries (e.g., `english_stem`). You can create custom dictionaries."],
  ["PostgreSQL", "How do you rank search results?", "rank-search-results", "Explain the `ts_rank` function.", "Use `ts_rank` or `ts_rank_cd` to compute relevance scores. Example: `SELECT *, ts_rank(to_tsvector('english', content), query) AS rank FROM documents, to_tsquery('english', 'search') query WHERE ... ORDER BY rank DESC;`."],
  ["PostgreSQL", "What is the purpose of `websearch_to_tsquery`?", "websearch-to-tsquery", "Explain the function.", "`websearch_to_tsquery` converts user input from a search bar (like Google) into a `tsquery`. It supports phrases, quotes, and OR. Example: `websearch_to_tsquery('english', 'search for \"exact phrase\"')`."],
  ["PostgreSQL", "What is a text search configuration?", "ts-configuration", "Define and explain.", "A text search configuration defines the parser, dictionaries, and mapping for a language. It controls how documents are tokenized and normalized. Example: `english`, `simple`, `german`. You can create custom configurations."],
  ["PostgreSQL", "How do you highlight search terms in results?", "highlight-search", "Explain the `ts_headline` function.", "`ts_headline` returns a fragment of the document with the search terms highlighted (using `<b>` tags). Example: `SELECT ts_headline('english', content, query) FROM ...`."],
  ["PostgreSQL", "What are stop words in full-text search?", "stop-words", "Define and explain.", "Stop words are common words (e.g., 'the', 'is', 'at') that are ignored during search because they add little value. They are defined in dictionaries. You can modify the stop word list."],
  ["PostgreSQL", "How do you support multiple languages in full-text search?", "multi-language-fts", "Explain the approach.", "Use language-specific text search configurations (e.g., `english`, `german`). Store the language of each document (or use a default). Use `setweight` to give different weights to different columns (e.g., title vs body)."],

  // ==================== JSON & JSONB (10) ====================
  ["PostgreSQL", "What is the JSONB data type and how is it different from JSON?", "jsonb-vs-json", "Explain the differences.", "JSONB stores JSON in a decomposed binary format, allowing faster indexing and querying. JSON stores plain text. JSONB supports indexing (GIN), more operators, and is recommended for most use cases."],
  ["PostgreSQL", "What operators are available for JSONB?", "jsonb-operators", "List common operators.", "`->` (get JSON object field as JSON), `->>` (get as text), `@>` (contains), `?` (key exists), `?|` (any key exists), `?&` (all keys exist), `||` (concatenate). Also, `#>` and `#>>` for path access."],
  ["PostgreSQL", "How do you create an index on JSONB data?", "jsonb-index", "Explain the indexing options.", "Use GIN index on the JSONB column. You can use the default `jsonb_ops` operator class or `jsonb_path_ops` for more compact indexes. Example: `CREATE INDEX idx_json ON table USING GIN (jsonb_column);`."],
  ["PostgreSQL", "What is the `jsonb_path_ops` operator class?", "jsonb-path-ops", "Explain its use.", "`jsonb_path_ops` is a GIN operator class optimized for `@>` (contains) queries. It is smaller and faster than default `jsonb_ops` for containment queries, but does not support all operators."],
  ["PostgreSQL", "How do you query specific keys in a JSONB column?", "jsonb-query", "Provide examples.", "`SELECT data->'name' FROM table;` for JSON output; `SELECT data->>'name' FROM table;` for text. `SELECT * FROM table WHERE data @> '{\"name\": \"John\"}';` for containment."],
  ["PostgreSQL", "How do you update a JSONB field?", "jsonb-update", "Explain the `jsonb_set` function.", "`jsonb_set` updates a JSONB field. Example: `UPDATE table SET data = jsonb_set(data, '{address, city}', '\"New York\"') WHERE id = 1;`. Also `jsonb_insert` for insertion."],
  ["PostgreSQL", "What is the difference between `jsonb_build_object` and `row_to_json`?", "jsonb_build_object-vs-row_to_json", "Compare the two.", "`jsonb_build_object` builds a JSON object from key-value pairs. `row_to_json` converts a row to a JSON object. Both produce JSONB; use `row_to_json` for converting query results."],
  ["PostgreSQL", "How do you aggregate JSONB data?", "jsonb-agg", "Explain `jsonb_agg`.", "`jsonb_agg` aggregates rows into a JSON array. Example: `SELECT jsonb_agg(data) FROM table;`."],
  ["PostgreSQL", "What is the `jsonb_array_length` function?", "jsonb-array-length", "Define and give example.", "`jsonb_array_length` returns the number of elements in a JSON array. Example: `SELECT jsonb_array_length(data->'items') FROM table;`."],
  ["PostgreSQL", "What are the advantages of using JSONB over relational columns?", "jsonb-advantages", "Explain the benefits.", "JSONB provides flexibility for schema-less data, reduces complexity for nested structures, and allows for fast queries when indexed. It is ideal for storing semi-structured data from external APIs."],

  // ==================== LOCKING & CONCURRENCY (10) ====================
  ["PostgreSQL", "What types of locks are used in PostgreSQL?", "lock-types", "List the types.", "Row-level locks: `FOR UPDATE`, `FOR SHARE`. Table-level locks: `ACCESS SHARE`, `ROW SHARE`, `ROW EXCLUSIVE`, `SHARE UPDATE EXCLUSIVE`, `SHARE`, `SHARE ROW EXCLUSIVE`, `EXCLUSIVE`, `ACCESS EXCLUSIVE` (the most restrictive)."],
  ["PostgreSQL", "What is the difference between `FOR UPDATE` and `FOR SHARE`?", "for-update-vs-for-share", "Compare the two.", "`FOR UPDATE` locks the rows for update; other transactions cannot modify or lock them. `FOR SHARE` locks the rows for reading; other transactions can still read but not modify. Use `FOR UPDATE` for writing."],
  ["PostgreSQL", "What is a deadlock and how does PostgreSQL handle it?", "deadlock-handling", "Explain the concept and resolution.", "A deadlock occurs when two or more transactions hold locks on resources that others need, causing them to wait indefinitely. PostgreSQL detects deadlocks and rolls back one of the transactions (by raising a `DEADLOCK_DETECTED` error). To avoid, ensure consistent lock ordering."],
  ["PostgreSQL", "How do you avoid long-running transactions?", "avoid-long-transactions", "Explain strategies.", "Long transactions hold locks and increase bloat. Break them into smaller batches. Use `commit` frequently. Avoid `VACUUM` issues. Monitor `pg_stat_activity` for idle-in-transaction connections."],
  ["PostgreSQL", "What is the purpose of `SET TRANSACTION`?", "set-transaction", "Explain the command.", "`SET TRANSACTION` sets the isolation level for the current transaction. Example: `SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;`. It affects how the transaction interacts with concurrent transactions."],
  ["PostgreSQL", "What is the `pg_advisory_lock` function?", "advisory-lock", "Explain custom locking.", "Advisory locks are application-level locks that do not depend on any table. They can be used to coordinate between processes. Functions: `pg_advisory_lock`, `pg_advisory_unlock`, `pg_try_advisory_lock`. They are useful for managing custom resource contention."],
  ["PostgreSQL", "How do you see current locks in PostgreSQL?", "view-locks", "Explain the `pg_locks` view.", "`pg_locks` shows all locks held by active transactions. You can join it with `pg_stat_activity` to see which queries are holding locks and who is waiting. Example: `SELECT * FROM pg_locks WHERE granted = false;`."],
  ["PostgreSQL", "What is the difference between `LOCK TABLE` and `SELECT ... FOR UPDATE`?", "lock-table-vs-for-update", "Compare the two.", "`LOCK TABLE` locks the entire table at a specified level, usually for DDL or heavy batch operations. `SELECT ... FOR UPDATE` locks only the selected rows, allowing other transactions to read other rows. Row-level locks are preferred for concurrency."],
  ["PostgreSQL", "What is a predicate lock and when is it used?", "predicate-lock", "Explain the concept.", "Predicate locks are used in serializable isolation to prevent phantom reads. They lock not only existing rows but also the conditions that would insert rows. They are managed automatically by PostgreSQL."],
  ["PostgreSQL", "How do you monitor lock contention?", "monitor-lock-contention", "Explain methods.", "Use `pg_stat_activity` to see queries that are waiting (`wait_event_type = 'Lock'`). Use `pg_locks` to see lock holders and waiters. Use `pg_blocking_pids()` to find blocking processes. Enable logging of lock waits (`log_lock_waits`)."],

  // ==================== CONFIGURATION & TUNING (10) ====================
  ["PostgreSQL", "What is the role of `shared_buffers` and how do you set it?", "shared-buffers", "Explain the memory setting.", "`shared_buffers` is the amount of memory PostgreSQL uses for caching data. It is one of the most important tuning parameters. A reasonable starting point is 25% of system memory. Increase it for read-heavy workloads, but do not exceed 50%."],
  ["PostgreSQL", "What is `work_mem` and when would you increase it?", "work-mem", "Explain per-operation memory.", "`work_mem` is the amount of memory used for sorting and hash operations. Increasing it can speed up complex queries, but it is per operation, so setting it too high can cause memory exhaustion. Tune based on query patterns."],
  ["PostgreSQL", "What is `effective_cache_size`?", "effective-cache-size", "Explain the estimate.", "`effective_cache_size` is an estimate of the operating system's cache size. The planner uses it to decide whether to use an index or sequential scan. Set it to the total memory available for OS cache (often 50-75% of RAM)."],
  ["PostgreSQL", "What is the `checkpoint` and how does it affect performance?", "checkpoint-tuning", "Explain checkpoint impact.", "A checkpoint flushes dirty buffers to disk. Frequent checkpoints reduce recovery time but cause I/O spikes. Tune `checkpoint_timeout` and `max_wal_size` to balance. Increase `checkpoint_completion_target` to spread the I/O load."],
  ["PostgreSQL", "What is the purpose of `wal_buffers`?", "wal-buffers", "Explain WAL memory.", "`wal_buffers` is the amount of memory used for WAL data before it is written to disk. The default is small; for write-heavy workloads, increase it to reduce disk I/O. Usually set to `-1` (auto-tuned)."],
  ["PostgreSQL", "How do you tune `max_connections`?", "max-connections", "Explain connection limits.", "`max_connections` is the maximum number of concurrent connections. Set it based on application needs and system resources. High connections increase memory usage (each connection uses ~2MB). Use connection pooling (PgBouncer) for high concurrency."],
  ["PostgreSQL", "What is `fsync` and why is it important?", "fsync", "Explain durability.", "`fsync` ensures that data is physically written to disk before a transaction commits. Disabling it (`fsync = off`) can improve performance but risks data corruption in case of a crash. Keep it enabled for production."],
  ["PostgreSQL", "What is `synchronous_commit` and when would you set it to `off`?", "synchronous-commit", "Explain the trade-off.", "`synchronous_commit` controls whether the commit waits for WAL flush to disk. Setting it to `off` improves performance but can lose up to a few seconds of data in a crash. Use it for non-critical workloads."],
  ["PostgreSQL", "How do you monitor cache hit ratio?", "cache-hit-ratio", "Explain the metric.", "Cache hit ratio = `(sum(heap_blks_hit) / (sum(heap_blks_hit) + sum(heap_blks_read))) * 100`. Lower ratios indicate insufficient caching; increase `shared_buffers` or add more memory."],
  ["PostgreSQL", "What is the `autovacuum` tuning and why is it important?", "autovacuum-tuning", "Explain autovacuum configuration.", "Autovacuum prevents bloat and updates statistics. Tune `autovacuum_vacuum_scale_factor`, `autovacuum_vacuum_threshold`, and `autovacuum_work_mem`. For large tables, reduce the scale factor. Monitor autovacuum activity with `pg_stat_autovacuum`."],

  // ==================== EXTENSIONS & MIGRATION (10) ====================
  ["PostgreSQL", "What is PostGIS and how is it used?", "postgis-definition", "Explain the spatial extension.", "PostGIS is a PostgreSQL extension that adds support for geographic objects, allowing spatial queries (e.g., distance, intersection). It is widely used for GIS applications. Example: `SELECT ST_Distance(ST_Point(1,2), ST_Point(3,4));`."],
  ["PostgreSQL", "What is `pgcrypto` and what does it provide?", "pgcrypto-definition", "Explain cryptographic functions.", "`pgcrypto` provides cryptographic functions (hashing, encryption, PGP). Use it for password hashing (`crypt`), data encryption (`encrypt`), and secure random generation (`gen_random_bytes`). It is installed as an extension."],
  ["PostgreSQL", "How do you install an extension in PostgreSQL?", "install-extension", "Provide the command.", "`CREATE EXTENSION extension_name;` Example: `CREATE EXTENSION pgcrypto;`. The extension files must be available in the PostgreSQL library directory. You can also create extensions with `--with-extension` at compile time."],
  ["PostgreSQL", "What is the `uuid-ossp` extension?", "uuid-ossp", "Explain the UUID generation.", "`uuid-ossp` provides functions to generate UUIDs (`uuid_generate_v4()`, `uuid_generate_v1()`). It is useful for primary keys. Install with `CREATE EXTENSION uuid-ossp;`."],
  ["PostgreSQL", "How do you migrate from MySQL to PostgreSQL?", "mysql-to-postgresql", "Explain the migration process.", "1. Export MySQL data using `mysqldump` with compatible options. 2. Use tools like `pgloader` or `mysql2postgres` to convert schema and data. 3. Adjust data types (e.g., `TINYINT` to `BOOLEAN`). 4. Test the migration. 5. Update applications to use PostgreSQL syntax."],
  ["PostgreSQL", "What is the `pg_dump` command and its options for migration?", "pg-dump-options", "Explain common options.", "`pg_dump -Fc` (custom format) for fast restore, `-t` for specific tables, `-schema` for schema-only, `--inserts` for INSERT statements. Use `pg_dumpall` for full cluster backup. Always include `-v` for verbose."],
  ["PostgreSQL", "How do you migrate a PostgreSQL database to a different version?", "pg-upgrade", "Explain major version upgrade.", "Use `pg_upgrade` with `--link` for fast upgrades. Steps: 1) Stop the old cluster. 2) Run `pg_upgrade` with old and new data directories. 3) Check the logs. 4) Start the new cluster. 5) Update statistics with `ANALYZE`."],
  ["PostgreSQL", "What is the `pg_restore` utility?", "pg-restore", "Explain the restore tool.", "`pg_restore` restores a database from a custom or directory format backup created by `pg_dump -Fc` or `-Fd`. It supports selective restore (`-t`, `-n`), parallel restore (`-j`), and single-transaction restore (`--single-transaction`)."],
  ["PostgreSQL", "What is the `psql` command-line tool and what are its useful meta-commands?", "psql-meta-commands", "List and explain common meta-commands.", "`\\l` list databases, `\\c` connect to database, `\\dt` list tables, `\\d table` describe table, `\\df` list functions, `\\?` help, `\\x` expanded output, `\\timing` toggle timing, `\\i file.sql` import SQL file."],
  ["PostgreSQL", "How do you backup only the schema of a database?", "schema-only-backup", "Provide the command.", "`pg_dump -s -U username -d dbname > schema.sql` or `pg_dump --schema-only -d dbname > schema.sql`. This excludes data."],

  // ==================== SCENARIO-BASED (20) ====================
  ["PostgreSQL", "A query is slow. How do you troubleshoot it?", "troubleshoot-slow-query", "Explain the diagnostic steps.", "1. Run `EXPLAIN ANALYZE` on the query. 2. Look for sequential scans, sorts, high cost. 3. Check if indexes are used. 4. Verify statistics (`ANALYZE`). 5. Check for locks (`pg_locks`, `pg_stat_activity`). 6. Consider query rewriting or adding indexes. 7. Check resource utilization (CPU, I/O, memory)."],
  ["PostgreSQL", "How do you handle table bloat?", "table-bloat", "Explain the problem and solution.", "Bloat occurs from dead rows caused by updates/deletes without VACUUM. Use `VACUUM` regularly. For severe bloat, use `VACUUM FULL` (locks table) or `pg_repack` (online). Monitor bloat with `pgstattuple` extension."],
  ["PostgreSQL", "A database is out of disk space. What do you do?", "disk-space-full", "Explain the recovery steps.", "1. Check free space: `df -h`. 2. Identify large objects: `SELECT pg_size_pretty(pg_total_relation_size('table'))`. 3. Remove old logs, WAL files if safe. 4. Consider vacuuming to free dead space. 5. Add more storage. 6. Archive old data."],
  ["PostgreSQL", "How do you restore a table from a dump without the entire database?", "restore-single-table", "Explain the procedure.", "Use `pg_restore` with `-t` (table) or `--table` from a custom dump. For plain SQL, you can extract the table section manually. You can also use `pg_dump -t table_name` to backup only that table."],
  ["PostgreSQL", "How do you delete a very large table without causing performance issues?", "delete-large-table", "Explain the best practices.", "Use `TRUNCATE` instead of `DELETE` for deleting all rows (fast but not DML). For selective deletion, break into batches with `DELETE ... WHERE ... LIMIT 1000` inside a loop. Use `VACUUM` afterward."],
  ["PostgreSQL", "How do you replicate data to another PostgreSQL instance?", "replication-setup", "Explain the methods.", "Use physical streaming replication (built-in) or logical replication (table-level). For physical, configure `wal_level = replica`, set up `recovery.conf` on standby. For logical, create publications and subscriptions."],
  ["PostgreSQL", "How do you handle a corrupted database?", "db-corruption", "Explain recovery options.", "If the database is corrupted, you can restore from a known good backup. If a specific table is corrupt, use `pg_dump` to dump that table (might work). If the WAL is intact, use `pg_resetwal` (risky). Otherwise, use tools like `pg_repack` or `pg_verifybackup`."],
  ["PostgreSQL", "How do you manage user roles and permissions in a multi-tenant application?", "multi-tenant-roles", "Explain the strategy.", "Use separate schemas per tenant, with a role per tenant. Grant permissions to those roles on their own schema. Use row-level security (RLS) if tenants share a schema. Use `SET ROLE` to switch context."],
  ["PostgreSQL", "What is the difference between `pg_dump` and `pg_dumpall`?", "pg-dump-vs-dumpall", "Compare the two.", "`pg_dump` backs up a single database. `pg_dumpall` backs up all databases and global objects (roles, tablespaces). Use `pg_dumpall` for full cluster backup."],
  ["PostgreSQL", "How do you upgrade PostgreSQL to a new major version?", "pg-upgrade", "Explain the process.", "Use `pg_upgrade` for in-place upgrades (with `--link` for fast migration). Also, use `pg_dumpall` + `psql` for logical upgrades. Always test and have backups. For logical upgrades, use `pg_dump` and restore to the new version."],
  ["PostgreSQL", "What is the `pg_stat_bgwriter` view used for?", "pg-stat-bgwriter", "Explain its purpose.", "`pg_stat_bgwriter` shows statistics about the background writer process, which writes dirty buffers to disk. It helps tune checkpoint and write performance. Metrics include buffers_clean, buffers_checkpoint, maxwritten_clean."],
  ["PostgreSQL", "How do you handle out-of-memory (OOM) issues?", "oom-issues", "Explain the strategies.", "Increase shared memory (`shared_buffers`, `work_mem`). Reduce `max_connections`. Use connection pooling (PgBouncer). Adjust Linux kernel parameters (`vm.overcommit_memory`). Monitor memory usage with `pg_stat_activity`."],
  ["PostgreSQL", "What is the purpose of `pg_restore` options `-j` and `-F`?", "pg-restore-options", "Explain the options.", "`-j` specifies the number of parallel workers for restore (improves performance). `-F` specifies the format (`c` for custom, `d` for directory format). Use both for faster large restores."],
  ["PostgreSQL", "How do you tune PostgreSQL for high write throughput?", "tune-for-write", "Explain configuration changes.", "Increase `checkpoint_completion_target` to spread writes. Increase `max_wal_size` to reduce checkpoint frequency. Use `synchronous_commit = off` (if acceptable). Use RAID 10 for WAL. Adjust `commit_delay` and `commit_siblings`."],
  ["PostgreSQL", "How do you handle connection saturation?", "connection-saturation", "Explain solutions.", "Use a connection pooler like PgBouncer. Tune `max_connections`. Optimize queries to release connections quickly. Monitor active connections and idle-in-transaction connections."],
  ["PostgreSQL", "What is the difference between `REFRESH MATERIALIZED VIEW CONCURRENTLY` and `REFRESH MATERIALIZED VIEW`?", "refresh-mv-concurrently", "Explain the difference.", "`REFRESH MATERIALIZED VIEW` locks the table and blocks reads. `REFRESH MATERIALIZED VIEW CONCURRENTLY` refreshes without locking, using a temporary table; it requires a unique index on the view. Use concurrently for high-availability."],
  ["PostgreSQL", "How do you perform a rolling upgrade of PostgreSQL?", "rolling-upgrade", "Explain the strategy.", "Use logical replication to replicate changes to a new version server. Gradually switch application traffic. Or use pg_upgrade with minimal downtime (using `--link`). Plan for failover and rollback."],
  ["PostgreSQL", "What is the purpose of `pg_stat_replication`?", "pg-stat-replication", "Explain the view.", "`pg_stat_replication` shows replication status: standby names, WAL send location, write lag, flush lag, replay lag. It helps monitor replication health and latency."],
  ["PostgreSQL", "How do you handle time zones in PostgreSQL?", "timezone-handling", "Explain the approach.", "Use `TIMESTAMPTZ` to store timestamps with time zone. Set `timezone` parameter for session/global default. Use `AT TIME ZONE` to convert. Store all timestamps in UTC internally."],
  ["PostgreSQL", "What is the `pg_notify` function used for?", "pg-notify", "Explain the asynchronous notification.", "`pg_notify` sends a notification to a channel. Used with `LISTEN` in clients to receive asynchronous events (e.g., for cache invalidation). It is part of the LISTEN/NOTIFY feature."]
] as const;





const prisma = new PrismaClient();

const buildWhyInterviewersAsk = (question: string, shortDescription: string) =>
  `Interviewers ask this to check whether you can explain PostgreSQL concepts clearly and connect them to practical engineering decisions. ${shortDescription} A strong response should address the purpose, the relevant trade-offs, and how you would verify the result rather than reciting a command or definition.`;

const buildCommonMistakes = (question: string) => [
  `Giving a memorized definition without explaining how it applies to: ${question}`,
  "Listing PostgreSQL commands without explaining the safety, performance, or operational trade-off.",
  "Ignoring security boundaries, persistence, failure handling, or how the solution would be tested.",
];

async function main() {
  const category = await prisma.category.upsert({
    where: { slug: "PostgreSQL" },
    update: { name: "PostgreSQL", group: "Technology", description: "PostgreSQL interview questions." },
    create: { name: "PostgreSQL", slug: "PostgreSQL", group: "Technology", description: "PostgreSQL interview questions." },
  });
  const subcategory = await prisma.subcategory.upsert({
    where: { categoryId_slug: { categoryId: category.id, slug: "PostgreSQL" } },
    update: {},
    create: { name: "PostgreSQL", slug: "PostgreSQL", categoryId: category.id },
  });

  for (let topicIndex = 0; topicIndex < topics.length; topicIndex += 1) {
    const [, question, slug, shortDescription, sampleAnswer] = topics[topicIndex];
    const commonMistakes = buildCommonMistakes(question);
    const followUpQuestions = [
      topics[(topicIndex + 1) % topics.length][1],
      topics[(topicIndex + 2) % topics.length][1],
      topics[(topicIndex + 3) % topics.length][1],
    ];
    await prisma.interviewQuestion.upsert({
      where: { slug },
      update: {
        question,
        categoryId: category.id,
        subcategoryId: subcategory.id,
        experienceLevel: ExperienceLevel.MID_LEVEL,
        difficulty: Difficulty.MEDIUM,
        interviewType: InterviewType.TECHNICAL,
        shortDescription,
        explanation: buildWhyInterviewersAsk(question, shortDescription),
        sampleAnswer,
        detailedAnswer: sampleAnswer,
        keyPoints: [],
        commonMistakes,
        followUpQuestions,
        tags: ["PostgreSQL"],
        isPublished: true,
      },
      create: {
        question,
        slug,
        categoryId: category.id,
        subcategoryId: subcategory.id,
        experienceLevel: ExperienceLevel.MID_LEVEL,
        difficulty: Difficulty.MEDIUM,
        interviewType: InterviewType.TECHNICAL,
        shortDescription,
        explanation: buildWhyInterviewersAsk(question, shortDescription),
        sampleAnswer,
        detailedAnswer: sampleAnswer,
        keyPoints: [],
        commonMistakes,
        followUpQuestions,
        tags: ["PostgreSQL"],
        isPublished: true,
      },
    });
  }

  console.log(`Imported ${topics.length} PostgreSQL questions.`);
}

main()
  .catch((error) => {
    console.error(error);
    process.exitCode = 1;
  })
  .finally(() => prisma.$disconnect());

export const slugify = (value: string) => value.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");